-- Fase 5: inteligência operacional, automações, relatórios e fundação segura para IA.

create table if not exists public.automation_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,event_type text not null,conditions jsonb not null default '{}'::jsonb,actions jsonb not null default '[]'::jsonb,active boolean not null default true,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists public.automation_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,rule_id uuid references public.automation_rules(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid,status text not null default 'processando' check(status in('processando','concluido','falhou','ignorado')),input_data jsonb not null default '{}'::jsonb,output_data jsonb not null default '{}'::jsonb,error_message text,started_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.saved_reports(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,report_type text not null,filters jsonb not null default '{}'::jsonb,schedule text,recipients text[] not null default '{}'::text[],active boolean not null default true,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists public.ai_query_audit(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,requested_by uuid references public.profiles(id) on delete set null,channel text not null default 'crm' check(channel in('crm','site','whatsapp','portal')),intent text not null,subject_type text,subject_id uuid,allowed boolean not null default false,fields_returned text[] not null default '{}'::text[],correlation_id uuid not null default gen_random_uuid(),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());

alter table public.reservations add column if not exists pipeline_id uuid references public.pipelines(id) on delete set null;
alter table public.reservations add column if not exists pipeline_stage_id uuid references public.pipeline_stages(id) on delete set null;
create index if not exists automation_rules_org_event_idx on public.automation_rules(organization_id,event_type,active);
create index if not exists automation_runs_org_started_idx on public.automation_runs(organization_id,started_at desc);
create index if not exists ai_query_audit_org_created_idx on public.ai_query_audit(organization_id,created_at desc);
create index if not exists reservations_org_pipeline_idx on public.reservations(organization_id,pipeline_stage_id,status);

alter table public.automation_rules enable row level security;alter table public.automation_runs enable row level security;alter table public.saved_reports enable row level security;alter table public.ai_query_audit enable row level security;
create policy automation_rules_managers on public.automation_rules for all to authenticated using(organization_id=public.current_organization_id() and public.has_role('administrador','gestor')) with check(organization_id=public.current_organization_id() and public.has_role('administrador','gestor'));
create policy automation_runs_managers_read on public.automation_runs for select to authenticated using(organization_id=public.current_organization_id() and public.has_role('administrador','gestor'));
create policy saved_reports_managers on public.saved_reports for all to authenticated using(organization_id=public.current_organization_id() and public.has_role('administrador','gestor')) with check(organization_id=public.current_organization_id() and public.has_role('administrador','gestor'));
create policy ai_query_audit_managers_read on public.ai_query_audit for select to authenticated using(organization_id=public.current_organization_id() and public.has_role('administrador','gestor'));

create or replace function public.create_first_contact_task() returns trigger language plpgsql security definer set search_path=public as $$declare task_id uuid;begin if new.deleted_at is not null then return new;end if;if not exists(select 1 from public.tasks t where t.lead_id=new.id and t.status<>'concluida' and t.title='Realizar primeiro contato') then insert into public.tasks(organization_id,lead_id,assigned_to,title,description,due_at,priority,status) values(new.organization_id,new.id,new.assigned_to,'Realizar primeiro contato','Contato automático criado pelo SLA comercial.',now()+interval '15 minutes','alta','pendente') returning id into task_id;insert into public.automation_runs(organization_id,event_type,entity_type,entity_id,status,output_data,finished_at) values(new.organization_id,'lead_created','lead',new.id,'concluido',jsonb_build_object('task_id',task_id),now());end if;return new;end $$;
drop trigger if exists create_first_contact_task_trigger on public.leads;create trigger create_first_contact_task_trigger after insert on public.leads for each row execute function public.create_first_contact_task();

create or replace function public.refresh_operational_alerts() returns jsonb language plpgsql security definer set search_path=public as $$declare org_id uuid;overdue_count integer:=0;document_count integer:=0;begin if not public.has_role('administrador','gestor') then raise exception 'acesso não autorizado';end if;org_id=public.current_organization_id();update public.payments p set status='atrasado',updated_at=now() from public.reservations r where p.reservation_id=r.id and r.organization_id=org_id and p.status='pendente' and p.due_date<current_date;get diagnostics overdue_count=row_count;select count(*) into document_count from public.document_requests d where d.organization_id=org_id and d.status='pendente' and d.due_at<now();insert into public.automation_runs(organization_id,event_type,entity_type,status,output_data,finished_at) values(org_id,'operational_health_check','organization','concluido',jsonb_build_object('payments_marked_overdue',overdue_count,'documents_overdue',document_count),now());return jsonb_build_object('payments_marked_overdue',overdue_count,'documents_overdue',document_count);end $$;
revoke all on function public.refresh_operational_alerts() from public,anon;grant execute on function public.refresh_operational_alerts() to authenticated;

create or replace function public.crm_report_summary(date_from date default(current_date-30),date_to date default current_date) returns jsonb language plpgsql stable security definer set search_path=public as $$declare org_id uuid;result jsonb;begin if not public.has_role('administrador','gestor') then raise exception 'acesso não autorizado';end if;org_id=public.current_organization_id();select jsonb_build_object('period',jsonb_build_object('from',date_from,'to',date_to),'leads',jsonb_build_object('total',(select count(*) from public.leads where organization_id=org_id and deleted_at is null and created_at::date between date_from and date_to),'converted',(select count(*) from public.leads where organization_id=org_id and deleted_at is null and converted_customer_id is not null and created_at::date between date_from and date_to),'lost',(select count(*) from public.leads where organization_id=org_id and deleted_at is null and status='perdido' and created_at::date between date_from and date_to),'unassigned',(select count(*) from public.leads where organization_id=org_id and deleted_at is null and assigned_to is null)),'reservations',jsonb_build_object('total',(select count(*) from public.reservations where organization_id=org_id and created_at::date between date_from and date_to),'confirmed',(select count(*) from public.reservations where organization_id=org_id and status='confirmada' and created_at::date between date_from and date_to),'revenue',(select coalesce(sum(final_value),0) from public.reservations where organization_id=org_id and status in('confirmada','concluida') and created_at::date between date_from and date_to)),'finance',jsonb_build_object('receivable',(select coalesce(sum(p.amount),0) from public.payments p join public.reservations r on r.id=p.reservation_id where r.organization_id=org_id and p.status in('pendente','atrasado')),'overdue',(select coalesce(sum(p.amount),0) from public.payments p join public.reservations r on r.id=p.reservation_id where r.organization_id=org_id and p.status='atrasado'),'paid',(select coalesce(sum(p.amount),0) from public.payments p join public.reservations r on r.id=p.reservation_id where r.organization_id=org_id and p.status='pago' and coalesce(p.paid_at,p.updated_at)::date between date_from and date_to)),'operations',jsonb_build_object('overdue_tasks',(select count(*) from public.tasks where organization_id=org_id and status<>'concluida' and due_at<now()),'pending_documents',(select count(*) from public.document_requests where organization_id=org_id and status='pendente'),'email_failures',(select count(*) from public.email_notifications where organization_id=org_id and status='falhou')),'sources',(select coalesce(jsonb_agg(row_data order by total desc),'[]'::jsonb) from(select jsonb_build_object('source',coalesce(source,'Não informado'),'total',count(*)) row_data,count(*) total from public.leads where organization_id=org_id and deleted_at is null and created_at::date between date_from and date_to group by source)s),'stages',(select coalesce(jsonb_agg(row_data order by total desc),'[]'::jsonb) from(select jsonb_build_object('stage',status::text,'total',count(*)) row_data,count(*) total from public.leads where organization_id=org_id and deleted_at is null group by status)s)) into result;return result;end $$;
revoke all on function public.crm_report_summary(date,date) from public,anon;grant execute on function public.crm_report_summary(date,date) to authenticated;

create or replace function public.crm_customer_answer_context(target_customer_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare result jsonb;begin if not public.can_access_customer(target_customer_id) then raise exception 'acesso não autorizado';end if;select jsonb_build_object('customer',jsonb_build_object('id',c.id,'name',c.name),'reservations',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'code',r.reservation_code,'status',r.status,'payment_status',r.payment_status,'next_payment',(select jsonb_build_object('description',p.description,'amount',p.amount,'due_date',p.due_date,'status',p.status) from public.payments p where p.reservation_id=r.id and p.status in('pendente','atrasado') order by p.due_date nulls last limit 1),'travelers',(select coalesce(jsonb_agg(jsonb_build_object('name',t.full_name,'document_status',t.document_status,'passport_status',t.passport_status,'visa_status',t.visa_status)),'[]'::jsonb) from public.reservation_travelers t where t.reservation_id=r.id)) order by r.created_at desc) from public.reservations r where r.customer_id=c.id),'[]'::jsonb)) into result from public.customers c where c.id=target_customer_id;insert into public.ai_query_audit(organization_id,requested_by,channel,intent,subject_type,subject_id,allowed,fields_returned) values(public.current_organization_id(),auth.uid(),'crm','customer_context','customer',target_customer_id,true,array['reservations','next_payment','document_status']);return result;end $$;
revoke all on function public.crm_customer_answer_context(uuid) from public,anon;grant execute on function public.crm_customer_answer_context(uuid) to authenticated;

create or replace function public.search_published_caravans(desired_month integer default null,desired_year integer default null,destination_query text default null) returns table(id uuid,name text,slug text,destination text,departure_date date,return_date date,status_public text,available_spots integer) language sql stable security definer set search_path=public as $$select c.id,c.name,c.slug,c.destination,c.departure_date,c.return_date,c.status_public,c.available_spots from public.caravans c where c.published=true and c.archived_at is null and c.departure_date>=current_date and(desired_month is null or extract(month from c.departure_date)=desired_month)and(desired_year is null or extract(year from c.departure_date)=desired_year)and(nullif(trim(destination_query),'') is null or c.destination ilike '%'||trim(destination_query)||'%' or c.name ilike '%'||trim(destination_query)||'%')order by c.departure_date limit 30$$;
revoke all on function public.search_published_caravans(integer,integer,text) from public;grant execute on function public.search_published_caravans(integer,integer,text) to anon,authenticated;

insert into public.automation_rules(organization_id,name,event_type,conditions,actions) values(public.default_organization_id(),'SLA de primeiro contato','lead_created','{"status":"novo_lead"}'::jsonb,'[{"type":"create_task","due_minutes":15,"priority":"alta"}]'::jsonb),(public.default_organization_id(),'Alerta de parcela vencida','operational_health_check','{"payment_status":"pendente","due":"past"}'::jsonb,'[{"type":"mark_overdue"},{"type":"notify_manager"}]'::jsonb),(public.default_organization_id(),'Alerta de documento pendente','operational_health_check','{"document_status":"pendente","due":"past"}'::jsonb,'[{"type":"notify_consultant"}]'::jsonb) on conflict(organization_id,name) do nothing;
insert into public.system_settings(organization_id,key,value) values(public.default_organization_id(),'ai_governance','{"enabled":false,"mode":"read_only","allowed_intents":["next_payment","document_status","published_caravans"],"require_identity_verification":true,"log_every_query":true,"human_handoff":true}'::jsonb) on conflict(organization_id,key) do update set value=excluded.value,updated_at=now();
